style.css:
/* The Odyssey — No Longer You | All websites */
/* i really want this to be global */

:root {
  /* swap these colors if you want */
  --my-ocean: #102b42;
  --my-deep: #081725;
  --my-seafoam: #9bd8ce;
  --my-gold: #d9b76b;
  --my-parchment: #eee2c5;
  --my-ink: #243342;
}

/* oceanic atmosphere */
html {
  background-color: var(--my-deep) !important;
  color-scheme: dark;
}

body {
  background-color: var(--my-deep) !important;
  background-image:
    radial-gradient(
      ellipse at 15% 15%,
      rgba(35, 105, 135, .30),
      transparent 55%
    ),
    radial-gradient(
      ellipse at 85% 85%,
      rgba(183, 144, 69, .14),
      transparent 50%
    ) !important;
  color: var(--my-parchment) !important;
}

/* mythological typography */
h1, h2, h3, h4 {
  color: var(--my-gold) !important;
  font-family: Georgia, "Times New Roman", serif !important;
  letter-spacing: .04em !important;
}

/* divine links */
a {
  color: var(--my-seafoam) !important;
  text-decoration-color: var(--my-gold) !important;
  transition: color .2s ease !important;
}

a:hover {
  color: var(--my-gold) !important;
}

/* ancient Greek inspired panels */
article, section, aside, main {
  border-color: rgba(217, 183, 107, .18) !important;
}

/* golden borders and soft corners */
button, input, textarea, select {
  border-color: rgba(217, 183, 107, .4) !important;
  border-radius: 9px !important;
}

/* divine buttons */
button {
  transition: background-color .2s ease, border-color .2s ease !important;
}

/* scroll like the waves of the Aegean */
* {
  scrollbar-color: #b99552 #102b42 !important;
}

::selection {
  background: var(--my-gold) !important;
  color: var(--my-deep) !important;
}

/* winion-inspired cursor */
html, body, a, button, input, textarea, select {
  cursor: url("https://cur.cursors-4u.net/nature/nat-11/nat1014.cur"), auto !important;
}

/* a little golden glow */
img {
  border-radius: 5px;
}
